#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"char *Descriptions[4]={"Количество газа", "Расход газа", "Температура", "Избыточное давление"};char *Formats[4]={"Tp1  Sm=%-.0fнм3", "Tp1  Qm=%-.5fнм3", "Tp1  T=%-.3f°C",  "Tp1  P=%-.3fкгс/см2"};typedef struct : public SPROLOZ  {	int nDisplayNumber; //определяет вид и содержание отображаемой информации	int nPHS;	int nSensors[4];    //индекс для доступа к значениям датчиак (по nDisplayNumber)  }   Queue_UVPScreen;int PaintUVPScreen(DefinePaint){  QueueP(Queue_UVPScreen);  CMyBrush brush (hDC, RGB(96,153,13), true);   ::Rectangle( hDC, p->mRect.left, p->mRect.top, p->mRect.right, p->mRect.bottom );  p->nDisplayNumber=-1;  if ( p->nPHS >= 0 )    {    CShPolyHS& Sh = (CShPolyHS&)q.m_pPipe->SH(p->nPHS);    if ( Sh.RetCode == CShBase::rcOK )		p->nDisplayNumber = Sh.SP;	if(p->nDisplayNumber<0 || p->nDisplayNumber >= _countof(p->nSensors))       p->nDisplayNumber=-1;	else{		RECT rect;		rect.left=p->mRect.left+6;		rect.top=p->mRect.top+2;		rect.right=p->mRect.right;		rect.bottom=p->mRect.top/2+p->mRect.bottom/2;		::DrawText(hDC, Descriptions[p->nDisplayNumber], -1, &rect, DT_SINGLELINE|DT_VCENTER|DT_LEFT );        CShSensor& Sh = (CShSensor&)q.m_pPipe->SH(p->nSensors[p->nDisplayNumber]);        if ( Sh.RetCode == CShBase::rcOK )		   {           char str[256];		   sprintf_s(str, _countof(str), Formats[p->nDisplayNumber], Sh.ShowValue);		   rect.top=rect.bottom+2;		   rect.bottom=p->mRect.bottom-2;		   ::DrawText(hDC, str, -1, &rect, DT_SINGLELINE|DT_VCENTER|DT_LEFT );		   }	    }    }  return 1;}void AddUVPScreen(DefineTegs){  AddQueueEx(Queue_UVPScreen);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintUVPScreen;  //  p->nPHS = def.AddKind(id_PHS, "UVP_Screen");  char szSensors[4][64];  memset(szSensors, 0, sizeof szSensors);  STegObj obj[] =    {    { 'R', "rect", &p->mRect },    { 'E', "rc"  , &p->mRect },	{ 'S', "sensor1", szSensors[0], 63 },	{ 'S', "sensor2", szSensors[1], 63 },	{ 'S', "sensor3", szSensors[2], 63 },	{ 'S', "sensor4", szSensors[3], 63 },    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  //  for(int ii=0; ii<_countof(p->nSensors); ii++)  {     p->nSensors[ii]=def.AddKind(id_Sensor, szSensors[ii]);  }}